window.kbPageData["views/entry/k-81ee46821e579981"] = {"key":"entry/k-81ee46821e579981","state":{"route":"entry/k-81ee46821e579981"},"node":{"id":"k-81ee46821e579981","mode":"k","title":"清池范式","type":"观点与论证","domain":"文化","reading":"","intro":"","priority":100,"aliases":["艺术乡建以村民为主体并立足本土文化"],"qs":["国考 2024 行政执法 申论#1"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"清池范式是冯教授团队在清池村探索的艺术乡建思路。它以尊重乡村主体和地方文化特色为前提，通过艺术实践引导村民重新认识乡村价值，参与家园建设。","review":{"definition":"清池范式是冯教授团队在清池村探索的艺术乡建思路。它以尊重乡村主体和地方文化特色为前提，通过艺术实践引导村民重新认识乡村价值，参与家园建设。","explanation":"冯教授认为，乡村价值既体现在山水、民居等可见风貌中，也体现在道德、伦理、信仰等深层文化中。本题用这一范式概括团队当好“运营官”的总体做法，共同改造、保留风貌、复原习俗和共创艺术是这一思路的具体体现。","references":[],"evidence":"通过艺术介入乡建，逐渐影响村民对于乡村价值的判断，引导村民回归家园、共建家园。","disposition":"题内说明","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 申论#1":{"paper":"国考 2024 行政执法 申论","n":1,"mod":"申论","src":["b9a9a500aad1608fddd0.pdf",4],"asrc":["b899d5c3aecda01e69ec.pdf",1],"card":"bb68bb01400c5dd4cc3f9d8f","links":[{"id":"k-81ee46821e579981","role":"直接考查","why":"这是清池范式的总体思路，说明艺术介入如何引导村民认同乡村价值并参与家园建设。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-81ee46821e579981":[["国考 2024 行政执法 申论#1"]]}};
